// Parse the scanner's machine-readable report and decide whether to alert.
const buf = await this.helpers.getBinaryDataBuffer(0, 'report');
const report = JSON.parse(buf.toString());
const s = report.summary;
const crit = s.advisories.open_by_severity.critical;
const high = s.advisories.open_by_severity.high;
const highPrio = s.access.by_priority.high;
const cfg = $('Config').item.json;

const lines = [];
lines.push(`GitHub org hygiene — ${s.org} (${s.mode})`);
lines.push(`Open advisories: ${s.advisories.total_open} (critical ${crit}, high ${high}).`);
if (s.advisories.oldest_unresolved) {
  const o = s.advisories.oldest_unresolved;
  lines.push(`Oldest unresolved: ${o.age_days}d — ${o.severity} in ${o.repo} (${o.package}).`);
}
lines.push(`Access reviews suggested: ${s.access.total_suggestions} (high ${s.access.by_priority.high}, medium ${s.access.by_priority.medium}, low ${s.access.by_priority.low}).`);
for (const w of (report.warnings || [])) lines.push(`! ${w}`);

// Alert if there is anything a security lead should look at this week.
const alert = (crit > 0) || (high > 0) || (highPrio > 0);

return [{ json: {
  org: s.org,
  mode: s.mode,
  critical: crit,
  high,
  highPrioritySuggestions: highPrio,
  totalSuggestions: s.access.total_suggestions,
  summaryText: lines.join('\n'),
  dashboardPath: `${cfg.outputDir}/dashboard.html`,
  alert
}}];
